CREATE TABLE anonymous_users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, alias VARCHAR(255) NOT NULL);
CREATE TABLE rooms (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(255) NOT NULL);
CREATE TABLE participants (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, room_id BIGINT NOT NULL REFERENCES rooms(id), anonymous_user_id BIGINT NOT NULL REFERENCES anonymous_users(id));
